from collections import deque

def levels(graph, start):
    """Group nodes by their distance from start (breadth-first)."""
    seen = {start}
    queue = deque([start])
    result = []
    while queue:
        level = []
        for _ in range(len(queue)):       # everything queued now is one level
            node = queue.popleft()
            level.append(node)
            for nxt in graph[node]:
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append(nxt)
        result.append(level)
    return result

graph = {"A": ["B", "C"], "B": ["D"], "C": ["D", "E"], "D": [], "E": ["A"]}
print(levels(graph, "A"))    # [['A'], ['B', 'C'], ['D', 'E']]

